-- Peso (kg) y medidas (cm) por SKU desde "Lista de Precios - Jeremías (6)".
-- v3 (2026-08-27): cubre TODA la lista (4723 SKUs con al menos un dato),
-- no solo los 244 del filtro Sin peso / Sin medidas. Los SKUs que no existen
-- en la tabla productos simplemente no matchean el join y se ignoran.
-- Solo escribe valores presentes (coalesce): no pisa con null lo ya cargado.
-- Valores imposibles de la fuente (peso > 100 kg o medida > 300 cm, ej.
-- SOLV1045 "185,000") se descartaron campo a campo. Los seriales de fecha
-- Excel en las medidas (46215 = "12,7") se recuperaron automáticamente.
-- metro_cubico se recalcula igual que la carga masiva (alto*largo*ancho, 2 dec)
-- cuando el producto queda con las tres medidas.
-- OJO: al ir directo a la base, esta carga NO queda en el Historial de cargas.

update public.productos p set
  peso  = coalesce(v.peso,  p.peso),
  largo = coalesce(v.largo, p.largo),
  ancho = coalesce(v.ancho, p.ancho),
  alto  = coalesce(v.alto,  p.alto),
  metro_cubico = case
    when coalesce(v.alto, p.alto) > 0
     and coalesce(v.largo, p.largo) > 0
     and coalesce(v.ancho, p.ancho) > 0
    then round((coalesce(v.alto, p.alto) * coalesce(v.largo, p.largo) * coalesce(v.ancho, p.ancho))::numeric, 2)
    else p.metro_cubico
  end
